dashboard.definition:
{
 "title": "The AI Stack",
 "description": "Six layers of enterprise AI, bottom-up: Cisco compute and storage, Cisco Nexus network, platform, applications, models and agents, with event counts, links and the five scoreboards",
 "inputs": {},
 "defaults": {
  "dataSources": {
   "global": {
    "options": {
     "queryParameters": {
      "earliest": "-30d@d",
      "latest": "now"
     }
    }
   }
  }
 },
 "dataSources": {
  "ds_layers": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count WHERE index IN (ai_infra,ai_network,ai_platform,ai_application,ai_model_eval) host=ai-demo-generator BY sourcetype | lookup ai_layer_map sourcetype OUTPUT layer layer_no dashboard | where isnotnull(layer_no) | stats sum(count) AS events BY layer_no | sort 0 layer_no",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Events by layer (24h)"
  },
  "ds_layer_06": {
   "type": "ds.chain",
   "name": "Layer 06",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=06 | fields events"
   }
  },
  "ds_layer_05": {
   "type": "ds.chain",
   "name": "Layer 05",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=05 | fields events"
   }
  },
  "ds_layer_04": {
   "type": "ds.chain",
   "name": "Layer 04",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=04 | fields events"
   }
  },
  "ds_layer_03": {
   "type": "ds.chain",
   "name": "Layer 03",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=03 | fields events"
   }
  },
  "ds_layer_02": {
   "type": "ds.chain",
   "name": "Layer 02",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=02 | fields events"
   }
  },
  "ds_layer_01": {
   "type": "ds.chain",
   "name": "Layer 01",
   "options": {
    "extend": "ds_layers",
    "query": "| search layer_no=01 | fields events"
   }
  },
  "ds_sb_reliability": {
   "type": "ds.search",
   "options": {
    "query": "`ai_scoreboard` scoreboard=\"reliability\" metric=\"Availability\" | stats latest(value) AS value",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Reliability: Availability"
  },
  "ds_sb_velocity": {
   "type": "ds.search",
   "options": {
    "query": "`ai_scoreboard` scoreboard=\"velocity\" metric=\"Pilot to production\" | stats latest(value) AS value",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Velocity: Pilot to production"
  },
  "ds_sb_efficiency": {
   "type": "ds.search",
   "options": {
    "query": "`ai_scoreboard` scoreboard=\"efficiency\" metric=\"GPU utilization\" | stats latest(value) AS value",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Efficiency: GPU utilization"
  },
  "ds_sb_trust": {
   "type": "ds.search",
   "options": {
    "query": "`ai_scoreboard` scoreboard=\"trust\" metric=\"Safety compliance\" | stats latest(value) AS value",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Trust: Safety compliance"
  },
  "ds_sb_security": {
   "type": "ds.search",
   "options": {
    "query": "`ai_scoreboard` scoreboard=\"security\" metric=\"Open findings\" | stats latest(value) AS value",
    "queryParameters": {
     "earliest": "-30d@d",
     "latest": "now"
    }
   },
   "name": "Security: Open findings"
  }
 },
 "visualizations": {
  "viz_header": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "# The AI Stack\n\nSix layers, one platform. Every layer feeds the same Splunk indexes, so an incident can be followed from a Cisco Nexus QoS change at the base to a hallucinating model and a runaway agent at the top. Click a layer to open its dashboard.",
    "fontColor": "#FFFFFF",
    "backgroundColor": "transparent",
    "fontSize": "default"
   }
  },
  "viz_rect_06": {
   "type": "splunk.rectangle",
   "options": {
    "fillColor": "#31373E",
    "fillOpacity": 1,
    "rx": 8,
    "strokeColor": "#31373E",
    "strokeWidth": 1
   }
  },
  "viz_md_06": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## 06 Agents\nAgent runs, steps, tool calls and outcomes  \n[Open AI Agents](/app/ai_infra_monitoring/ai_agents)",
    "fontColor": "#FFFFFF",
    "backgroundColor": "transparent",
    "fontSize": "default"
   }
  },
  "viz_count_06": {
   "type": "splunk.singlevalueicon",
   "title": "",
   "dataSources": {
    "primary": "ds_layer_06"
   },
   "options": {
    "icon": "user",
    "iconPosition": "before",
    "iconColor": "#00CDAF",
    "iconOpacity": 1,
    "showValue": true,
    "majorColor": "#FFFFFF",
    "majorFontSize": 36,
    "shouldAbbreviateMajorValue": true,
    "underLabel": "events, last 24h",
    "backgroundColor": "transparent"
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToDashboard",
     "options": {
      "app": "ai_infra_monitoring",
      "dashboard": "ai_agents",
      "newTab": false
     }
    }
   ]
  },
  "viz_rect_05": {
   "type": "splunk.rectangle",
   "options": {
    "fillColor": "#31373E",
    "fillOpacity": 1,
    "rx": 8,
    "strokeColor": "#31373E",
    "strokeWidth": 1
   }
  },
  "viz_md_05": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## 05 Models\nQuality scores and evaluation evidence by model and version  \n[Open Model Performance and Quality](/app/ai_infra_monitoring/model_performance_quality)",
    "fontColor": "#FFFFFF",
    "backgroundColor": "transparent",
    "fontSize": "default"
   }
  },
  "viz_count_05": {
   "type": "splunk.singlevalueicon",
   "title": "",
   "dataSources": {
    "primary": "ds_layer_05"
   },
   "options": {
    "icon": "star",
    "iconPosition": "before",
    "iconColor": "#00CDAF",
    "iconOpacity": 1,
    "showValue": true,
    "majorColor": "#FFFFFF",
    "majorFontSize": 36,
    "shouldAbbreviateMajorValue": true,
    "underLabel": "events, last 24h",
    "backgroundColor": "transparent"
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToDashboard",
     "options": {
      "app": "ai_infra_monitoring",
      "dashboard": "model_performance_quality",
      "newTab": false
     }
    }
   ]
  },
  "viz_rect_04": {
   "type": "splunk.rectangle",
   "options": {
    "fillColor": "#31373E",
    "fillOpacity": 1,
    "rx": 8,
    "strokeColor": "#31373E",
    "strokeWidth": 1
   }
  },
  "viz_md_04": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## 04 Applications\nRequests, latency, tokens, cost and guardrails, correlated by trace ID  \n[Open AI Applications](/app/ai_infra_monitoring/ai_applications)",
    "fontColor": "#FFFFFF",
    "backgroundColor": "transparent",
    "fontSize": "default"
   }
  },
  "viz_count_04": {
   "type": "splunk.singlevalueicon",
   "title": "",
   "dataSources": {
    "primary": "ds_layer_04"
   },
   "options": {
    "icon": "apps",
    "iconPosition": "before",
    "iconColor": "#00CDAF",
    "iconOpacity": 1,
    "showValue": true,
    "majorColor": "#FFFFFF",
    "majorFontSize": 36,
    "shouldAbbreviateMajorValue": true,
    "underLabel": "events, last 24h",
    "backgroundColor": "transparent"
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToDashboard",
     "options": {
      "app": "ai_infra_monitoring",
      "dashboard": "ai_applications",
      "newTab": false
