  "viz_md_03": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## 03 Platform\nKubernetes, inference serving and evaluation and fine-tuning jobs  \n[Open AI Platform and Workloads](/app/ai_infra_monitoring/ai_platform_workloads)",
    "fontColor": "#FFFFFF",
    "backgroundColor": "transparent",
    "fontSize": "default"
   }
